import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第五十一卦震 震為雷 震上震下","description":"周易 - 第五十一卦震 震為雷 震上震下","frontmatter":{"title":"第五十一卦震 震為雷 震上震下","description":"周易 - 第五十一卦震 震為雷 震上震下"},"headers":[],"relativePath":"classics/zhouyi/052.md","filePath":"classics/zhouyi/052.md"}'),l={name:"classics/zhouyi/052.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="震為雷" tabindex="-1">震為雷 <a class="header-anchor" href="#震為雷" aria-label="Permalink to “震為雷”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨。震來虩虩，笑言啞啞。震驚百里，不喪匕鬯。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>震，亨。震來虩虩，恐致福也。笑言啞啞，後有則也。震驚百里，驚遠而懼邇也。出可以守宗廟社稷，以為祭主也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>洊雷，震；君子以恐懼修身。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>震來虩虩，後笑言啞啞，吉。象曰：震來虩虩，恐致福也。笑言啞啞，後有則也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>震來厲，億喪貝，躋於九陵，勿逐，七日得。象曰：震來厲，乘剛也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>震蘇蘇，震行無眚。象曰：震蘇蘇，位不當也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>震遂泥。象曰：震遂泥，未光也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>震往來厲，億無喪，有事。象曰：震往來厲，危行也。其事在中，大無喪也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。婚媾有言。象曰：震索索，未得中也。雖兇無咎，畏鄰戒也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
